const jwt = require("jsonwebtoken");

function authenticate(req, res, next) {
  const token = (req.headers.authorization || "").replace(/^Bearer /, "");
  try {
    const c = jwt.verify(token, PUBLIC_KEY, {
      algorithms: ["RS256"],
      issuer: "https://auth.kintai.example",
      audience: "kintai-api",
    });
    req.user = { id: c.sub, tenantId: c.tid, role: c.role };
    next();
  } catch (e) {
    return res.status(401).end();
  }
}

function requireRole(...roles) {
  return (req, res, next) =>
    roles.includes(req.user.role) ? next() : res.status(403).end();
}

// (1) 勤怠記録の参照
app.get("/api/v1/timesheets/:id", authenticate, async (req, res) => {
  const ts = await db.timesheets.findById(req.params.id);
  if (!ts) return res.status(404).end();
  if (req.user.role === "member" && ts.userId !== req.user.id) {
    return res.status(403).end();
  }
  res.json(ts);
});

// (2) 勤怠記録の承認
app.post("/api/v1/timesheets/:id/approve", authenticate,
  requireRole("manager", "admin"), async (req, res) => {
  const ts = await db.timesheets.findOne({ id: req.params.id, tenantId: req.user.tenantId });
  if (!ts) return res.status(404).end();
  ts.status = "approved";
  ts.approvedBy = req.user.id;
  await db.timesheets.save(ts);
  res.json(ts);
});

// (3) チームの所属者一覧
app.get("/api/v1/teams/:teamId/members", authenticate,
  requireRole("manager", "admin"), async (req, res) => {
  const team = await db.teams.findOne({ id: req.params.teamId, tenantId: req.user.tenantId });
  if (!team) return res.status(404).end();
  res.json(await db.users.find({ teamId: team.id, tenantId: req.user.tenantId }));
});

// (4) 自身の利用者情報の更新
app.patch("/api/v1/users/me", authenticate, async (req, res) => {
  const u = await db.users.findOne({ id: req.user.id, tenantId: req.user.tenantId });
  Object.assign(u, req.body);
  await db.users.save(u);
  res.json(toPublic(u));
});

// (5) 自テナントの利用者名簿
app.get("/api/v1/users", authenticate, async (req, res) => {
  const list = await db.users.find({ tenantId: req.user.tenantId });
  res.json(list.map(toPublic));
});

server {
    listen 443 ssl;
    server_name www.x-shop.example;
    ssl_certificate     /etc/nginx/tls/www.crt;   # RSA 2048ビットの鍵の証明書だけを設定
    ssl_certificate_key /etc/nginx/tls/www.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-RSA-AES256-GCM-SHA384:AES128-GCM-SHA256:AES256-SHA';
    ssl_prefer_server_ciphers on;
    ssl_ecdh_curve X25519:prime256v1;
}
